#!/usr/bin/env bash\nset -uo pipefail\nTARGET_DIR="${1:-target}"\nENGINE="${AUDIT_ENGINE:-all}"\nREPORT_DIR="$RUNNER_TEMP/flutter-foundry-audit-reports"\nSUMMARY_FILE="$REPORT_DIR/results.tsv"\nmkdir -p "$REPORT_DIR"\n: > "$SUMMARY_FILE"\nif [[ ! -d "$TARGET_DIR" ]]; then echo "Target directory does not exist: $TARGET_DIR" >&2; exit 2; fi\nrun_scan() {\n  local name="$1"; shift\n  local log="$REPORT_DIR/$name.log"; local code=0\n  printf 'Running %s...\n' "$name"\n  "$@" >"$log" 2>&1 || code=$?\n  printf '%s\t%s\n' "$name" "$code" >> "$SUMMARY_FILE"\n  if [[ "$code" -eq 0 ]]; then printf '%s completed (exit 0).\n' "$name"; else printf '%s exited %s. This can mean findings or scanner/setup problems; inspect its report.\n' "$name" "$code"; fi\n  return 0\n}\nrun_scan_json() {\n  local name="$1"; local report="$2"; shift 2\n  local log="$REPORT_DIR/$name.log"; local code=0\n  printf 'Running %s...\n' "$name"\n  "$@" >"$report" 2>"$log" || code=$?\n  printf '%s\t%s\n' "$name" "$code" >> "$SUMMARY_FILE"\n  if [[ "$code" -eq 0 ]]; then printf '%s completed (exit 0).\n' "$name"; else printf '%s exited %s. This can mean findings or scanner/setup problems; inspect %s and %s.\n' "$name" "$report" "$log"; fi\n  return 0\n}\nshould_run() { [[ "$ENGINE" == "all" || "$ENGINE" == "$1" ]]; }\nif should_run trivy; then run_scan trivy docker run --rm -v "$PWD/$TARGET_DIR:/src:ro" -v "$REPORT_DIR:/out" aquasec/trivy:latest fs --scanners vuln,misconfig --skip-dirs .git --format json --output /out/trivy.json /src; fi\nif should_run gitleaks; then run_scan gitleaks docker run --rm -v "$PWD/$TARGET_DIR:/src:ro" -v "$REPORT_DIR:/out" ghcr.io/gitleaks/gitleaks:v8.30.1 dir --redact --report-format json --report-path /out/gitleaks.json /src; fi\nif should_run semgrep; then run_scan semgrep docker run --rm -v "$PWD/$TARGET_DIR:/src:ro" -v "$REPORT_DIR:/out" semgrep/semgrep:latest semgrep scan --config auto --json --output /out/semgrep.json /src; fi\nif should_run osv-scanner; then run_scan_json osv-scanner "$REPORT_DIR/osv-scanner.json" docker run --rm -v "$PWD/$TARGET_DIR:/src:ro" -v "$REPORT_DIR:/out" ghcr.io/google/osv-scanner:v2.3.3 scan source -r /src --format json; fi\nif should_run zizmor; then\n  if [[ -d "$TARGET_DIR/.github/workflows" ]]; then\n    pipx install zizmor >/dev/null 2>&1 || true\n    if command -v zizmor >/dev/null 2>&1; then run_scan zizmor zizmor "$TARGET_DIR/.github/workflows"\n    else printf 'zizmor\t127\n' >> "$SUMMARY_FILE"; echo "zizmor could not be installed via pipx." > "$REPORT_DIR/zizmor.log"; fi\n  else printf 'zizmor\t0\n' >> "$SUMMARY_FILE"; echo "No .github/workflows directory found; zizmor skipped." > "$REPORT_DIR/zizmor.log"; fi\nfi\nif should_run ruff; then\n  if find "$TARGET_DIR" -type f -name '*.py' -print -quit | grep -q .; then\n    pipx install ruff >/dev/null 2>&1 || true\n    if command -v ruff >/dev/null 2>&1; then run_scan_json ruff "$REPORT_DIR/ruff.json" ruff check --output-format=json "$TARGET_DIR"\n    else printf 'ruff\t127\n' >> "$SUMMARY_FILE"; echo "ruff could not be installed via pipx." > "$REPORT_DIR/ruff.log"; fi\n  else printf 'ruff\t0\n' >> "$SUMMARY_FILE"; echo "No Python files found; ruff skipped." > "$REPORT_DIR/ruff.log"; fi\nfi\nif should_run shellcheck; then\n  if find "$TARGET_DIR" -type f -name '*.sh' -print -quit | grep -q .; then\n    sudo apt-get update >/dev/null 2>&1 && sudo apt-get install --yes shellcheck >/dev/null 2>&1\n    mapfile -d '' files < <(find "$TARGET_DIR" -type f -name '*.sh' -print0)\n    if command -v shellcheck >/dev/null 2>&1; then run_scan_json shellcheck "$REPORT_DIR/shellcheck.json" shellcheck -f json "${files[@]}"\n    else printf 'shellcheck\t127\n' >> "$SUMMARY_FILE"; echo "shellcheck could not be installed." > "$REPORT_DIR/shellcheck.log"; fi\n  else printf 'shellcheck\t0\n' >> "$SUMMARY_FILE"; echo "No shell scripts found; ShellCheck skipped." > "$REPORT_DIR/shellcheck.log"; fi\nfi\nif should_run biome; then\n  if find "$TARGET_DIR" -type f \( -name '*.js' -o -name '*.jsx' -o -name '*.ts' -o -name '*.tsx' -o -name '*.json' -o -name '*.css' \) -print -quit | grep -q .; then run_scan_json biome "$REPORT_DIR/biome.json" npm exec --yes --package=@biomejs/biome -- biome check "$TARGET_DIR" --reporter=json\n  else printf 'biome\t0\n' >> "$SUMMARY_FILE"; echo "No supported JS/TS/JSON/CSS files found; Biome skipped." > "$REPORT_DIR/biome.log"; fi\nfi\n{\n  echo "# Audit report"; echo\n  echo "- Target: $TARGET_REPOSITORY@$TARGET_REF"\n  echo "- Engine selection: $ENGINE"\n  echo "- Exit code 0 means the command completed; non-zero can mean findings or scanner/configuration problems."\n  echo "- The workflow scans files and does not run target build scripts or package install scripts."\n  echo; echo "| Scanner | Exit code |"; echo "|---|---:|"\n  while IFS=$'\t' read -r name code; do [[ -n "${name:-}" ]] || continue; echo "| $name | $code |"; done < "$SUMMARY_FILE"\n  echo; echo "Download the artifact for individual scanner logs and machine-readable reports."\n} > "$REPORT_DIR/summary.md"\ncat "$REPORT_DIR/summary.md" >> "$GITHUB_STEP_SUMMARY"\necho "Audit complete. Detailed logs and reports are in $REPORT_DIR."\nexit 0\n